import { useState } from "react";

import ProgressBar from "./ProgressBar"

export default function App() {
    const [progress, setProgress] = useState(0);
    return (
        <div>
            <ProgressBar progress={progress} />
            <button>Increase Progress</button>
        </div>
    );
}
